static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array, *cov_array;

    // Parse NumPy arrays
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &cov_array))
        return NULL;

    if (PyArray_TYPE(weights_array) != NPY_DOUBLE ||
        PyArray_TYPE(cov_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "weights and covariance must be float64 arrays");
        return NULL;
    }
    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "weights must be 1-D and covariance must be 2-D");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) < n || PyArray_DIM(cov_array, 1) < n) {
        PyErr_SetString(PyExc_ValueError, "covariance matrix dimensions do not match weights");
        return NULL;
    }

    const double *weights = (const double *)PyArray_DATA(weights_array);
    const char *cov_data = (const char *)PyArray_DATA(cov_array);
    npy_intp w_stride = PyArray_STRIDE(weights_array, 0) / (npy_intp)sizeof(double);
    npy_intp row_stride = PyArray_STRIDE(cov_array, 0);
    npy_intp col_stride = PyArray_STRIDE(cov_array, 1);

    // Compute x^T * S * x using the same accumulation order as the baseline.
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const char *row = cov_data + i * row_stride;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            double cov_ij = *(const double *)(row + j * col_stride);
            row_sum += cov_ij * weights[j * w_stride];
        }
        risk_squared += weights[i * w_stride] * row_sum;
    }

    if (risk_squared < 0.0 && risk_squared > -1e-15)
        risk_squared = 0.0;

    return PyFloat_FromDouble(sqrt(risk_squared));
}

