/*
 * High-performance portfolio calculations using C extension
 *
 * Supports both NumPy float64 arrays (zero-copy) and plain Python
 * lists/tuples directly, avoiding an expensive list-to-array conversion
 * when the caller supplies the baseline's nested lists.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* ------------------------------------------------------------------ */
/* Helpers for plain Python sequences                                  */
/* ------------------------------------------------------------------ */

static inline int is_sequence(PyObject *obj) {
    return PyList_Check(obj) || PyTuple_Check(obj);
}

static inline Py_ssize_t sequence_size(PyObject *obj) {
    return PyList_Check(obj) ? PyList_GET_SIZE(obj) : PyTuple_GET_SIZE(obj);
}

static inline PyObject *sequence_item(PyObject *obj, Py_ssize_t i) {
    return PyList_Check(obj) ? PyList_GET_ITEM(obj, i)
                             : PyTuple_GET_ITEM(obj, i);
}

static inline int sequence_get_double(PyObject *obj, Py_ssize_t i,
                                      double *value) {
    PyObject *item = sequence_item(obj, i);
    if (PyFloat_Check(item)) {
        *value = PyFloat_AS_DOUBLE(item);
        return 1;
    }

    double v = PyFloat_AsDouble(item);
    if (v == -1.0 && PyErr_Occurred())
        return 0;
    *value = v;
    return 1;
}

static PyObject *portfolio_risk_from_sequences(PyObject *weights_obj,
                                               PyObject *cov_obj) {
    Py_ssize_t n = sequence_size(weights_obj);
    Py_ssize_t cov_n = sequence_size(cov_obj);

    if (cov_n < n) {
        PyErr_SetString(PyExc_ValueError,
                        "covariance matrix dimensions do not match weights");
        return NULL;
    }

    double *weights = PyMem_Malloc((size_t)n * sizeof(double));
    if (weights == NULL) {
        PyErr_NoMemory();
        return NULL;
    }

    for (Py_ssize_t i = 0; i < n; ++i) {
        if (!sequence_get_double(weights_obj, i, &weights[i])) {
            PyMem_Free(weights);
            return NULL;
        }
    }

    /* Same accumulation order as the pure-Python baseline. */
    double risk_squared = 0.0;
    for (Py_ssize_t i = 0; i < n; ++i) {
        PyObject *row = sequence_item(cov_obj, i);
        if (!is_sequence(row) || sequence_size(row) < n) {
            PyErr_SetString(PyExc_ValueError,
                            "covariance matrix dimensions do not match weights");
            PyMem_Free(weights);
            return NULL;
        }

        double row_sum = 0.0;
        for (Py_ssize_t j = 0; j < n; ++j) {
            double cov_ij;
            if (!sequence_get_double(row, j, &cov_ij)) {
                PyMem_Free(weights);
                return NULL;
            }
            row_sum += cov_ij * weights[j];
        }
        risk_squared += weights[i] * row_sum;
    }

    PyMem_Free(weights);

    if (risk_squared < 0.0 && risk_squared > -1e-15)
        risk_squared = 0.0;

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject *portfolio_return_from_sequences(PyObject *weights_obj,
                                                 PyObject *returns_obj) {
    Py_ssize_t n = sequence_size(weights_obj);
    if (sequence_size(returns_obj) < n) {
        PyErr_SetString(PyExc_ValueError,
                        "returns array is shorter than weights");
        return NULL;
    }

    double total_return = 0.0;
    for (Py_ssize_t i = 0; i < n; ++i) {
        double weight, expected_return;
        if (!sequence_get_double(weights_obj, i, &weight) ||
            !sequence_get_double(returns_obj, i, &expected_return))
            return NULL;
        total_return += weight * expected_return;
    }

    return PyFloat_FromDouble(total_return);
}

/* ------------------------------------------------------------------ */
/* NumPy array paths                                                   */
/* ------------------------------------------------------------------ */

static PyObject *portfolio_risk_from_arrays(PyObject *weights_obj,
                                            PyObject *cov_obj) {
    if (!PyArray_Check(weights_obj) || !PyArray_Check(cov_obj)) {
        PyErr_SetString(PyExc_TypeError,
                        "expected NumPy arrays or Python sequences");
        return NULL;
    }

    PyArrayObject *weights_array = (PyArrayObject *)weights_obj;
    PyArrayObject *cov_array = (PyArrayObject *)cov_obj;

    if (PyArray_TYPE(weights_array) != NPY_DOUBLE ||
        PyArray_TYPE(cov_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError,
                        "weights and covariance must be float64 arrays");
        return NULL;
    }
    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError,
                        "weights must be 1-D and covariance must be 2-D");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) < n || PyArray_DIM(cov_array, 1) < n) {
        PyErr_SetString(PyExc_ValueError,
                        "covariance matrix dimensions do not match weights");
        return NULL;
    }

    const double *weights = (const double *)PyArray_DATA(weights_array);
    const char *cov_data = (const char *)PyArray_DATA(cov_array);
    npy_intp w_stride =
        PyArray_STRIDE(weights_array, 0) / (npy_intp)sizeof(double);
    npy_intp row_stride = PyArray_STRIDE(cov_array, 0);
    npy_intp col_stride = PyArray_STRIDE(cov_array, 1);

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const char *row = cov_data + i * row_stride;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            double cov_ij = *(const double *)(row + j * col_stride);
            row_sum += cov_ij * weights[j * w_stride];
        }
        risk_squared += weights[i * w_stride] * row_sum;
    }

    if (risk_squared < 0.0 && risk_squared > -1e-15)
        risk_squared = 0.0;

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject *portfolio_return_from_arrays(PyObject *weights_obj,
                                              PyObject *returns_obj) {
    if (!PyArray_Check(weights_obj) || !PyArray_Check(returns_obj)) {
        PyErr_SetString(PyExc_TypeError,
                        "expected NumPy arrays or Python sequences");
        return NULL;
    }

    PyArrayObject *weights_array = (PyArrayObject *)weights_obj;
    PyArrayObject *returns_array = (PyArrayObject *)returns_obj;

    if (PyArray_TYPE(weights_array) != NPY_DOUBLE ||
        PyArray_TYPE(returns_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError,
                        "weights and returns must be float64 arrays");
        return NULL;
    }
    if (PyArray_NDIM(weights_array) != 1 ||
        PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and returns must be 1-D arrays");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) < n) {
        PyErr_SetString(PyExc_ValueError,
                        "returns array is shorter than weights");
        return NULL;
    }

    const double *weights = (const double *)PyArray_DATA(weights_array);
    const double *returns = (const double *)PyArray_DATA(returns_array);
    npy_intp w_stride =
        PyArray_STRIDE(weights_array, 0) / (npy_intp)sizeof(double);
    npy_intp r_stride =
        PyArray_STRIDE(returns_array, 0) / (npy_intp)sizeof(double);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total_return += weights[i * w_stride] * returns[i * r_stride];

    return PyFloat_FromDouble(total_return);
}

/* ------------------------------------------------------------------ */
/* Python entry points                                                 */
/* ------------------------------------------------------------------ */

static PyObject *portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    if (is_sequence(weights_obj) && is_sequence(cov_obj))
        return portfolio_risk_from_sequences(weights_obj, cov_obj);

    return portfolio_risk_from_arrays(weights_obj, cov_obj);
}

static PyObject *portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    if (is_sequence(weights_obj) && is_sequence(returns_obj))
        return portfolio_return_from_sequences(weights_obj, returns_obj);

    return portfolio_return_from_arrays(weights_obj, returns_obj);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS,
     "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS,
     "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  /* Initialize NumPy C API */
    return PyModule_Create(&moduledef);
}

